INSERT INTO player_game_stats VALUES(79,'FC26','2026-07-23',76,'잭슨',259197,'N. Jackson','FC Bayern München (대출)','ST','ST',24,187,'€24.5M',79,82,82,77,69,79,40,78,'{"크로스": 62, "결정력": 81, "헤딩 정확도": 76, "짧은 패스": 77, "발리 슛": 76, "드리블": 81, "커브": 72, "프리킥 정확도": 50, "긴 패스": 62, "볼컨트롤": 79, "가속": 81, "질주 속도": 83, "민첩성": 72, "반응력": 79, "균형 감각": 71, "슈팅력": 79, "점프": 89, "체력": 81, "힘": 77, "중거리슛": 70, "공격성": 72, "차단력": 40, "공격 위치 선정": 83, "시야": 73, "페널티킥": 60, "침착": 77, "방어인식": 30, "스탠딩 태클": 40, "슬라이딩 태클": 30, "GK 몸 날리기": 12, "GK 핸들링": 7, "GK 킥력": 12, "GK 위치 선정": 7, "GK 반사신경": 7}','낮은 드리븐 슛;게임 체인저;테크니컬','','{"st_advanced": 1}','어드밴스 포워드 +/ST/공격지원다재다능','Controlled Lengthy','린(185+)','오른쪽','2026-07-30','https://sofifa.com/player/259197/nicolas-jackson/260046/','HIGH — sofifa 선수 상세 페이지 직접 스크레이프. ⚠️ roster_date 2026-07-23으로 타 행(2026-06-30)과 다름 — 동일 시점 비교 시 유의. 소속은 바이에른 임대 상태로 표기되며 빌라행은 HIGH 루머 단계. / [2026-07-31 HyperMotion 수집] sofifa 선수 상세에서 가속력 유형(AcceleRATE)·체형·선호발·역할상세(역할+숙련도/포지션/가용포커스) 추가. obs#88이 EA 행동 4요소 중 하나로 지목한 HyperMotion 축의 결손을 메운다. / 🔄 **[2026-07-31 obs#115 — 중복 병합]** 같은 `sofifa_id`에 이름 변형으로 두 행이 생겨 있었다(`UNIQUE(game_version, name_kr)`가 못 막는다). 최신 `roster_date` 행을 남기고 옛 행의 세부 데이터(attrs·role_familiarity·playstyles·detail_date)를 이 행으로 옮긴 뒤 옛 행을 제거했다 — 정보 손실 0. 이 정리는 SSOT 3단계(라벨 매핑)의 선행 조건이었다: 한 툴 키에 두 DB 행이 후보가 되면 생성 결과가 **비결정적**이 된다.',NULL,NULL);
INSERT INTO player_game_stats VALUES(80,'FC26','2026-04-09',78,'마테오 루헤리',259584,'Matteo Ruggeri','Atlético Madrid','LB,LWB,LM','LB',24,187,'€16.0M',77,83,78,60,73,71,72,73,NULL,'에어리얼 포트리스;휩 패스',NULL,NULL,NULL,'Controlled Lengthy','Lean 187cm','왼발','2026-04-09','sofifa.com/player/259584/matteo-ruggeri/260031 (검색 경유) · ea.com/games/ea-sports-fc/ratings/player-ratings/matteo-ruggeri/259584 · fcratings.com/matteo-ruggeri-259584','OVR·POT·가치·베스트포지션(LB 77)·체형·가속은 sofifa 2026-04 로스터 기준(런치 75/LM → 1월 76 → 3월 이후 77/LB, 크로스 77→79 상향, 역할 LB 윙백/어택킹윙백 추가, ''Aerial Fortress'' PS 추가). 6대 스탯(78/60/73/71/72/73)은 EA 공식 페이지의 런치값 — sofifa 페이지 직접 접근이 403이라 4월판 정확 6스탯은 미확인(상향분 소폭 미반영 가능). 참고: fcratings.com은 FC27 선행치 78 OVR·PAC 81을 이미 게시.',NULL,NULL);
INSERT INTO player_game_stats VALUES(81,'FC26','2026-06-30',90,'완비사카',229880,'A. Wan-Bissaka','West Ham United','RB,RM','RB',27,183,'€17M',79,79,79,51,69,76,77,73,'{"크로스": 72, "결정력": 46, "헤딩 정확도": 56, "짧은 패스": 75, "발리 슛": 43, "드리블": 78, "커브": 74, "프리킥 정확도": 45, "긴 패스": 58, "볼컨트롤": 73, "가속": 79, "질주 속도": 79, "민첩성": 77, "반응력": 77, "균형 감각": 70, "슈팅력": 70, "점프": 75, "체력": 75, "힘": 71, "중거리슛": 44, "공격성": 73, "차단력": 79, "공격 위치 선정": 72, "시야": 68, "페널티킥": 44, "침착": 78, "방어인식": 78, "스탠딩 태클": 79, "슬라이딩 태클": 88, "GK 몸 날리기": 9, "GK 핸들링": 8, "GK 킥력": 6, "GK 위치 선정": 8, "GK 반사신경": 8}','Slide Tackle+;Block;Intercept;Anticipate;Rapid','','{"fb_wingback": 1}','Wingback +/RB/Balanced','Controlled','Unique','오른쪽','2026-08-14','cmtracker FC26 roster 2026-06-30 https://cmtracker.net/en/players/26063000/229880/aaron-wan-bissaka (역할숙련도·AcceleRATE·체형·플레이스타일 확보) ; sofifa 검색 페이지 FC26 roster 2026-07-23 https://sofifa.com/players?keyword=Wan-Bissaka (35속성 교차검증·EUR 가치) ; EA 공식 https://www.ea.com/games/ea-sports-fc/ratings/player-ratings/aaron-wan-bissaka/229880 (플레이스타일 원장)','MEDIUM-HIGH — 35개 속성은 cmtracker(06-30)·sofifa(07-23) 두 소스에서 **완전 일치**해 교차검증됐다. ⚠️ **[소스 이탈]** 이 표의 다른 행은 전부 sofifa 상세 페이지 스크레이프인데, sofifa 선수 상세가 **로그인 게이트**로 막혀(2026-08-14 확인) 역할숙련도·AcceleRATE·체형·플레이스타일을 cmtracker에서 받았다. 계정 생성은 하지 않았다. / ⚠️ **[face stat 3사 불일치]** PAC/SHO/PAS/DRI/DEF/PHY가 소스마다 다르다 — 저장값은 sofifa(79/51/69/76/77/73), cmtracker는 79/53/65/76/76/74, EA 공식은 80/51/69/77/78/73(OVR도 80). 35속성이 동일한데 6종합만 갈리므로 **사이트별 산출 공식 차이**이지 로스터 차이가 아니다. 슬롯 비교에 6종합을 쓸 때 이 행을 다른 행과 직접 비교하지 말 것. / ⚠️ **[언어 이탈]** playstyles·role_detail이 영문이다 — 한글 라벨의 출처인 sofifa 상세가 막혀 EA 공식 영문 표기를 그대로 뒀다. 한글 라벨을 추측해 넣지 않았다. / ⭐ **[AcceleRATE 검증]** docs/20 ⑤ 공식으로 계산하면 민첩77−힘71=6(<10, Explosive 탈락) · 힘71−민첩77=−6(<4, Lengthy 탈락) → **Controlled**이고, cmtracker 실측 표기도 **Controlled**로 **일치**한다. (웹 검색 요약에 ''Controlled Lengthy''라는 서술이 있었으나 원 페이지에서 오류로 확인돼 기각.) / ⚠️ **[구단 상태]** 로스터의 ''West Ham United / Premier League'' 표기는 25/26 시즌 기준이다. 웨스트햄은 **2026-05-24 18위(39점)로 강등**돼 26/27은 챔피언십이다(PL 공식 확인).',NULL,NULL);
INSERT INTO player_game_stats VALUES(82,'FC26','2026-07-23',132,'스즈키',255981,'Z. Suzuki','Parma','GK','GK',23,190,'€5.5M',74,80,73,72,71,76,56,74,'{"크로스": 12, "결정력": 6, "헤딩 정확도": 12, "짧은 패스": 21, "발리 슛": 7, "드리블": 14, "커브": 13, "긴 패스": 23, "볼컨트롤": 11, "가속": 55, "질주 속도": 58, "민첩성": 59, "반응력": 72, "균형 감각": 33, "슈팅력": 53, "점프": 73, "체력": 23, "힘": 78, "중거리슛": 8, "차단력": 7, "공격 위치 선정": 7, "시야": 46, "페널티킥": 18, "침착": 39, "방어인식": 8, "스탠딩 태클": 16, "슬라이딩 태클": 13, "GK 몸 날리기": 73, "GK 핸들링": 72, "GK 킥력": 71, "GK 위치 선정": 74, "GK 반사신경": 76, "프리킥 정확도": 11, "공격성": 26}','긴패스;디플렉터',NULL,'{"gk_ballplaying": 1}','볼플레잉 키퍼 +/GK/빌드업','Controlled Lengthy','Stocky(185+)','오른쪽','2026-08-18','https://sofifa.com/players?keyword=Zion+Suzuki (FC26 roster 2026-07-23, 검색 페이지 컬럼 스크레이프 2026-08-16) + https://sofifa.com/player/255981/ (상세 페이지 2026-08-18 직접 수집 — 페이지 로스터 표기 ''2026. 7. 23.''로 이 행과 동일 시점)',unistr('MEDIUM-HIGH — sofifa 검색 페이지 컬럼 실측. ⛔ **선수 상세 페이지가 로그인 게이트라 접근 불가**(2026-08-16) — 기존 행들이 상세에서 가져온 **playstyles·traits·role_familiarity·accelerate(AcceleRATE)·body_type은 전부 미수집**이다. ⚠️ **6대 스탯(DIV/HAN/KIC/REF/SPD/POS)은 직접 스크레이프되지 않아 GK 원능력치에서 매핑**했다 — DIV/HAN/KIC/REF/POS는 원능력치 그대로, DEF 칸(=SPD)은 (가속+질주)/2. 이 규칙은 마르티네스 기존 행(83/81/82/85/56/85 ↔ 원능력치 83/81/82/85·가속55·질주57)으로 **재현 검증**했다. ⚠️ **프리킥 정확도·공격성 2개 능력치는 미수집**(컬럼 코드 미확인). ⚠️ sofifa 표기 나이가 **22세**인데 실제로는 23세다(2002-08-21생, roster 2026-07-23 기준) — FC26 로스터의 나이 필드가 1년 뒤처져 있다. 나이 기반 판단에 그대로 쓰지 말 것.\u000a⭐ **[2026-08-18 상세 페이지 결손 해소]** sofifa 상세가 **로그인 세션에서는 열린다**(사용자 로그인 후 확인) — 08-16의 ⛔로그인 게이트는 ''로그인 없이 불가''로 좁혀야 한다. 페이지 상단 로스터 표기가 **''2026. 7. 23.''로 이 행과 같은 시점**이라 교차-로스터 추정 없이 그대로 채웠다: playstyles(긴패스·디플렉터 — **PS+ 없음**) · role_familiarity `{"gk_ballplaying": 1}` · role_detail `볼플레잉 키퍼 +/GK/빌드업` · accelerate `Controlled Lengthy`(가속력 유형 ''제어된 길게 가속'') · body_type `Stocky(185+)` · attrs에 **프리킥 정확도 11 · 공격성 26** 보강(08-16 ''컬럼 코드 미확인'' 결손 해소). ⭐ **role_detail 문자열이 마르티네스와 완전히 동일하다** — EA도 그를 스위퍼가 아니라 볼플레잉 키퍼로 분류한다(obs#234). ⛔ **traits(특산품)는 결손이 아니라 실측 ''없음''이다** — 상세 페이지의 특산품 블록이 비어 있다(결손과 0의 구분, obs#132). 그 외 상세 전용 값: 반대 발 3 · 개인기 1 · 국제 인지도 1 · 91kg · 주급 €9K · 출시조항 €11M · 계약 2029 · 입단 2024-07-15 (대응 컬럼이 없어 미적재). ⚠️ 나이 표기는 상세에서도 **22세**로 1년 뒤처져 있다(2002-08-21생 ⇒ 실제 23세) — 08-16 판정 유지.'),NULL,NULL);
INSERT INTO player_game_stats VALUES(83,'FC26','2026-07-23',1,'마르티네스',202811,'E. Martínez','Aston Villa','GK','GK',32,195,'€26.5M',85,85,83,81,82,85,56,85,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'오른쪽',NULL,'https://sofifa.com/players?tm[]=<2|5|9>&showCol[]=… (FC26 roster 2026-07-23, 2026-08-19 메인 세션 브라우저 팀 필터 스크레이프). ⭐ 재수집 URL 규약: `tm[]`=팀id(AVL 2 · CHE 5 · LIV 9), `showCol[]`에 ae,oa,pt,bp,hi,pf,vl,wg,tt,ir + **pac,sho,pas,dri,def,phy** + 원능력치(cr,fi,he,sh,vo,cu,lo,bl,ac,sp,ag,ba,so,ju,st,sr,ln,in,po,pe,ma,sa,sl,vi,cm,re,dp) + GK(gd,gh,gc,gp,gr). 국적·풀네임·sofifa_id는 행 DOM에서 추출한다(img.flag[title] · a[data-tippy-content] · href /player/<id>/).','MEDIUM-HIGH — sofifa 검색 페이지 팀 필터 실측(로그인 불필요). ⭐ **FC26→FC27 델타 베이스라인 목적의 3팀 전 스쿼드 보강**이다 (기존 FC26 82행이 빌라 22·첼시 2·리버풀 0으로 편중돼 첼시·리버풀 델타를 낼 수 없었다). ⭐⭐ **스킬 문서의 「6대 스탯(PAC/SHO/PAS/DRI/DEF/PHY) 컬럼은 스크레이프되지 않는다」는 틀렸다** — `showCol[]=pac,sho,pas,dri,def,phy`로 직접 받아진다. 마르티네스 83/81/82/85/56/85가 기존 행과 정확히 일치해 재현 검증됐다. ⇒ GK 원능력치 매핑 규칙(DEF칸=SPD=(가속+질주)/2)은 **더 이상 필요하지 않다**(다만 그 규칙이 옳았음도 함께 확인됐다). ⛔ **원능력치(attrs)는 이번에 적재하지 않았다** — 델타 산출에 불필요해 생략했고 위 URL로 언제든 보강 가능하다. **결손이며 0이 아니다.** ⛔ **playstyles·traits·role_familiarity·AcceleRATE·body_type도 미적재**(상세 페이지 전용, 로그인 필요 — obs#234). ⚠️ **이 로스터는 2026 여름 이적창을 반영하지 않는다** — 틸레만스·로저스·디뉴·산초·두글라스 루이스가 여전히 빌라로, 살라가 여전히 리버풀로 잡혀 있다. **로스터 시점의 기록이며 현재 소속이 아니다**(불변규칙 2 — 시점 그대로 보존). ⚠️ sofifa 나이는 1년 뒤처질 수 있다(obs#234) — 나이 판단에 그대로 쓰지 말 것.','Argentina/Spain','Emiliano Martínez');
