INSERT INTO player_game_stats VALUES(180,'FC26','2026-07-23',55,'만잠비',276694,'J. Manzambi','SC Freiburg','CM,CDM,CAM','CAM',19,183,'€22.5M',77,86,78,71,70,82,69,71,'{"크로스": 58, "결정력": 71, "헤딩 정확도": 63, "짧은 패스": 79, "발리 슛": 61, "커브": 56, "긴 패스": 73, "볼컨트롤": 80, "가속": 81, "질주 속도": 75, "민첩성": 80, "반응력": 78, "균형 감각": 78, "슈팅력": 80, "점프": 78, "체력": 77, "힘": 69, "중거리슛": 69, "차단력": 75, "공격 위치 선정": 75, "시야": 74, "페널티킥": 53, "침착": 73, "방어인식": 66, "스탠딩 태클": 74, "슬라이딩 태클": 59, "GK 몸 날리기": 8, "GK 핸들링": 10, "GK 킥력": 8, "GK 위치 선정": 13, "GK 반사신경": 9}',NULL,NULL,NULL,NULL,NULL,NULL,'오른쪽',NULL,'https://sofifa.com/players?keyword=Manzambi&showCol[]=… (FC26 roster 2026-07-23, 2026-08-19 메인 세션 브라우저 직접 스크레이프) — ⭐ **소속팀 `SC Freiburg 2024 ~ 2030` · 국적 `Switzerland` · 포지션 `CM,CDM,CAM` 3요소 대조 완료**(docs/30 선수 동일성 확인 규약)','MEDIUM-HIGH — sofifa 검색 페이지 실측. ⭐ **FC27 빌라 top-11에 만잠비가 포함됐는데 FC26 베이스라인이 없어 델타를 낼 수 없었던 결손을 메운다** (08-19 3팀 수집은 `tm[]` 팀 필터라 **당시 프라이부르크 소속이던 그가 빠졌다**). ⭐ **원능력치(attrs) 31개를 함께 적재했다** — 3팀 86행은 델타 목적상 attrs를 생략했으나 이 행은 1명이라 전부 받았다. ⛔ playstyles·traits·role_familiarity·AcceleRATE·body_type은 여전히 미적재(상세 페이지 로그인 전용, obs#234). ⛔ **프리킥 정확도·공격성 2개는 컬럼 코드가 없어 미수집**이다. ⚠️ **이 행의 소속은 SC Freiburg이고 빌라가 아니다** — 로스터 시점(2026-07-23) 그대로 보존한다(불변규칙 2). 빌라 합류는 CONFIRMED이나 FC26 로스터에는 반영되지 않았다.','Switzerland','Johan Manzambi');
INSERT INTO player_game_stats VALUES(181,'FC26','2026-07-23',178,'하우드-벨리스',252793,'T. Harwood-Bellis','Southampton FC 2024~2028','CB','CDM',23,188,'€8M',74,81,65,36,62,66,74,78,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'오른쪽',NULL,'sofifa 검색 페이지 FC26 roster 2026-07-23 (roster id 260046) — https://sofifa.com/players?keyword=<name>&showCol[]=pac,sho,pas,dri,def,phy,oa,pt,bp,hi,pf,vl,wg,ae (in-app 브라우저, 2026-08-21 수집)','[2026-08-21] 검색 페이지 컬럼 스크레이프. ⛔ **`attrs`(35속성)·`playstyles`·`traits`·`role_familiarity`·`accelerate`·`body_type`은 NULL이다** — sofifa 선수 상세 페이지가 **로그인 게이트**로 막혀 있어 받지 못했다(계정 생성은 하지 않았다). 결손과 0을 구분해 NULL로 뒀다(obs#132). cmtracker 경로로 보완 가능하나 이번 회차 미실시. ⚠️ **sofifa 나이 표기가 1년 뒤처진다** — 표기값을 그대로 저장했고 실제 나이는 `players.birth_year`로 판단할 것 (예: 톰모리 표기 27 ↔ 실제 28, 하우드-벨리스 표기 23 ↔ 실제 24). ⚠️ 주급은 스키마에 컬럼이 없어 이 칸에 기록한다. 주급 €37K.','England',NULL);
